signature.code:
function useQuerySelect<TData, TError = Error>(
  queryKey: QueryKey,
  options?: QueryOptions<TData>
): QueryState<TData, TError>

examples.code:
import { useQuerySelect } from '@qortex/query-react';

function UserName({ userId }: { userId: string }) {
  const userState = useQuerySelect(['user', userId], {
    fetcher: async () => {
      const response = await fetch(`/api/users/${userId}`);
      return response.json();
    }
  });

  // Only re-renders when userState.data changes, not when other state properties change
  return <span>{userState.data?.name ?? 'Unknown'}</span>;
}

import { useQuerySelect } from '@qortex/query-react';

function ProductStats({ productId }: { productId: string }) {
  const productState = useQuerySelect(['product', productId], {
    fetcher: async () => {
      const response = await fetch(`/api/products/${productId}`);
      return response.json();
    }
  });

  // Component only re-renders when accessed state properties change
  return (
    <div>
      <h3>{productState.data?.name ?? 'Unknown Product'}</h3>
      <p>Price: ${productState.data?.price ?? 0}</p>
      <p>In Stock: {(productState.data?.inventory ?? 0) > 0 ? 'Yes' : 'No'}</p>
      {productState.isLoading && <div>Loading...</div>}
      {productState.isError && <div>Error: {productState.error?.message}</div>}
    </div>
  );
}
